contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        require(c.owner() != address(this));
        bool reverted;
        c.owned();
        reverted = false;
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public {
        require(c.owner() == address(0));
        require(newOwner != address(0));
        bool reverted;
        c.transferOwnership(newOwner);
        reverted = true;
        assert(reverted && c.owner() == address(0));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public {
        bool r1;
        try c.owned() { r1 = false; } catch { r1 = true; }
        bool r2;
        try c.transferOwnership(newOwner) { r2 = false; } catch { r2 = true; }
        assert(r1 && r2 && c.owner() == address(0));
    }
    receive() external payable {}
}
